fn SpanMapper_new_(source: &String) -> Self_ {
    let mut line_starts = vec![0];
    for _item in source.char_indices() {
        if ((ch == "\n".to_string())) { line_starts.push(((idx + 1))) };
    }
    SpanMapper { source: source.to_string(), line_starts: line_starts }
}

fn SpanMapper_span_to_location(_self: &Self_, span: crate::span::Span, file: &String) -> SourceLocation {
    if _self.line_starts.is_empty() { return SourceLocation__new_(file, 1, 1); };
    let start = span.start.min(_self.source.len());
    let line_idx = match _self.line_starts.binary_search(&start) { Ok(idx) => idx, Err(idx) => idx.saturating_sub(1) };
    let line_start = _self.line_starts[line_idx];
    let col = start.saturating_sub(line_start);
    SourceLocation__new_(file, ((line_idx + 1)), ((col + 1)))
}

fn SpanMapper_source(_self: &Self_) -> &String {
    &_self.source
}

