fn test_line_info() {
    let source = "let x = 5\nlet y = x + 1\nprint(y)".to_string();
    let diag = Diagnostics__new_(source, "test.kn".to_string());
    let _ = diag.get_line_info(crate__span__Span__new_(0, 3));
    assert_eq!(line_, 1);
    assert_eq!(col, 1);
    assert_eq!(content, "let x = 5".to_string());
    let _ = diag.get_line_info(crate__span__Span__new_(14, 15));
    assert_eq!(line_, 2);
    assert_eq!(content, "let y = x + 1".to_string());
}

fn test_span_mapper_basic() {
    let source = "let x = 5\nlet y = x + 1\nprint(y)".to_string();
    let mapper = SpanMapper__new_(source);
    let loc = mapper.span_to_location(crate__span__Span__new_(0, 3), "test.kn".to_string());
    assert_eq!(loc.file, "test.kn".to_string());
    assert_eq!(loc.line_, 1);
    assert_eq!(loc.col, 1);
    let loc = mapper.span_to_location(crate__span__Span__new_(4, 5), "test.kn".to_string());
    assert_eq!(loc.line_, 1);
    assert_eq!(loc.col, 5);
    let loc = mapper.span_to_location(crate__span__Span__new_(10, 13), "test.kn".to_string());
    assert_eq!(loc.line_, 2);
    assert_eq!(loc.col, 1);
    let loc = mapper.span_to_location(crate__span__Span__new_(14, 15), "test.kn".to_string());
    assert_eq!(loc.line_, 2);
    assert_eq!(loc.col, 5);
    let loc = mapper.span_to_location(crate__span__Span__new_(24, 29), "test.kn".to_string());
    assert_eq!(loc.line_, 3);
    assert_eq!(loc.col, 1);
}

