enum ErrorKind {
    Parse,
    Type,
    Validation,
    Codegen,
    Io,
    Config,
}

fn ErrorKind_fmt(_self: &Self_, f: &mut std::fmt::Formatter) -> Result<(), Error> {
    match _self { Parse => write!(f, "{}", "PARSE".to_string()), Type => write!(f, "{}", "TYPE".to_string()), Validation => write!(f, "{}", "VALIDATION".to_string()), Codegen => write!(f, "{}", "CODEGEN".to_string()), Io => write!(f, "{}", "IO".to_string()), Config => write!(f, "{}", "CONFIG".to_string()) }
}

fn format_enhanced_error(kind: &ErrorKind, code: &crate::diagnostic_registry::DiagnosticCode, file: &Option<std::path::PathBuf>, location: &Option<(usize, usize)>, context: &String, message: &String, suggestion: &Option<String>) -> String {
    let spec = crate__diagnostic_registry__spec_for_code(((*code)));
    let mut output = String__new_();
    output.push_str(&format!("{}{}{}{}{}{}", "❌ [".to_string(), kind, ":".to_string(), spec.code_str, "] ".to_string(), spec.title));
    match file { Some(path) => { output.push_str(&format!("{}{}", " in ".to_string(), path.display())); match location { Some((line_, col)) => output.push_str(&format!("{}{}{}{}", ":".to_string(), line_, ":".to_string(), col)), _ => None } }, _ => None };
    output.push_str("\n\n".to_string());
    if ((!context.is_empty())) { output.push_str(&format!("{}{}{}", "   Context: ".to_string(), context, "\\n".to_string())) };
    output.push_str(&format!("{}{}{}", "   ".to_string(), message, "\\n".to_string()));
    match suggestion.as_deref().or_(spec.default_suggestion) { Some(suggestion) => output.push_str(&format!("{}{}{}", "\\n   Help: ".to_string(), suggestion, "\\n".to_string())), _ => None };
    match spec.docs_key { Some(docs_key) => output.push_str(&format!("{}{}{}", "\\n   Reference: ".to_string(), docs_key, "\\n".to_string())), _ => None };
    output
}

fn format_multi_errors(errors: &[KainError]) -> String {
    let mut output = String__new_();
    output.push_str(&format!("{}{}{}", "Found ".to_string(), errors.len(), " error(s):\\n".to_string()));
    for _item in errors.iter().enumerate() {
        output.push_str(&format!("{}{}{}{}{}{}{}", "\\n[".to_string(), ((i + 1)), "/".to_string(), errors.len(), "] ".to_string(), err, "\\n".to_string()));
    }
    output
}

