fn parse_program(source: &String) -> Result<Program, Error> {
    let tokens = (crate__lexer__Lexer__new_(source).tokenize()?);
    let span_mapper = crate__diagnostics__SpanMapper__new_(source);
    Parser__new_(&tokens, &span_mapper, "<test>".to_string()).parse()
}

fn parses_component_call_and_fragment_in_component_render() {
    let program = parse_program("component App():\n    render <Fragment><Panel title={title} /></Fragment>\n".to_string()).expect("program should parse".to_string());
    let _ = &program.items[0];
    match &component_.body { Fragment(children, _) => { assert_eq!(children.len(), 1); match &children[0] { _ => { assert_eq!(name, "Panel".to_string()); assert_eq!(props.len(), 1) }, other => panic!("expected component call, got {other:?}".to_string()) } }, other => panic!("expected fragment body, got {other:?}".to_string()) };
}

fn parses_jsx_if_and_for_children() {
    let program = parse_program("component App(items: List<Int>, ready: Bool):\n    render <div>{if ready: <Spinner /> else: <Empty />}{for item in items: <Row value={item} />}</div>\n".to_string()).expect("program should parse".to_string());
    let _ = &program.items[0];
    let _ = &component_.body;
    assert_eq!(children.len(), 2);
    match &children[0] { _ => { assert!(None); assert!(None) }, other => panic!("expected if child, got {other:?}".to_string()) };
    match &children[1] { _ => { assert_eq!(binding, "item".to_string()); assert!(None) }, other => panic!("expected for child, got {other:?}".to_string()) };
}

fn parses_jsx_attributes_named_like_keywords() {
    let program = parse_program("component App():\n    render <button type=\"button\" className={none}>\"ok\"</button>\n".to_string()).expect("program should parse".to_string());
    let _ = &program.items[0];
    let _ = &component_.body;
    assert_eq!(attributes.len(), 2);
    assert_eq!(attributes[0].name, "type".to_string());
    assert_eq!(attributes[1].name, "className".to_string());
}

fn parses_component_valued_jsx_attributes() {
    let program = parse_program("component App():\n    render <Shell topBar={<TopBar title={title} />} bottom={<Footer />} />\n".to_string()).expect("program should parse".to_string());
    let _ = &program.items[0];
    let _ = &component_.body;
    assert_eq!(props.len(), 2);
    match &props[0].value { Expr(JSX(_, _)) => assert_eq!(name, "TopBar".to_string()), other => panic!("expected nested JSX component prop, got {other:?}".to_string()) };
    match &props[1].value { Expr(JSX(_, _)) => assert_eq!(name, "Footer".to_string()), other => panic!("expected nested JSX component prop, got {other:?}".to_string()) };
}

fn py_to_value(obj: &PyAny) -> PyResult<Value> {
    match obj.extract() { Ok(s) => Ok(Value__String(s)), _ => None };
    match obj.extract() { Ok(b) => Ok(Value__Bool(b)), _ => None };
    match obj.extract() { Ok(i) => Ok(Value__Int(i)), _ => None };
    match obj.extract() { Ok(f) => Ok(Value__Float(f)), _ => None };
    match obj.downcast() { Ok(l) => { let mut vec = Vec__new_(); for item in l { vec.push((py_to_value(item)?)) } return Ok(Value__Array(std__sync__Arc__new_(std__sync__RwLock__new_(vec)))); }, _ => None };
    Ok(Value__String(obj))
}

