#[derive(Debug, Clone, Default)]
struct TempTestDir {
    pub path: std::path::PathBuf,
}

fn TempTestDir_new_(name: &String) -> Self_ {
    let temp_dir = std__env__temp_dir().join(format!("{}{}", "kain_test_".to_string(), name));
    if temp_dir.exists() { let _ = std__fs__remove_dir_all(&temp_dir); };
    std__fs__create_dir_all(&temp_dir).expect("Failed to create temp dir".to_string());
    (temp_dir,)
}

fn TempTestDir_create_file(_self: &Self_, relative_path: &String, content: &String) {
    let file_path = _self.path.join(relative_path);
    match file_path.parent() { Some(parent) => std__fs__create_dir_all(parent).expect("Failed to create parent dirs".to_string()), _ => None };
    std__fs__write(&file_path, content).expect("Failed to write file".to_string());
}

fn TempTestDir_create_dir(_self: &Self_, relative_path: &String) {
    let dir_path = _self.path.join(relative_path);
    std__fs__create_dir_all(&dir_path).expect("Failed to create directory".to_string());
}

fn TempTestDir_path(_self: &Self_) -> &std::path::PathBuf {
    &_self.path
}

fn TempTestDir_drop(_self: &mut Self_) {
    let _ = std__fs__remove_dir_all(&_self.path);
}

